import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import FormAtividadeModal from '../components/FormAtividadeModal';
import { apiService } from '../services/api';

const useParamsMock = vi.fn(() => ({}));

vi.mock('react-router-dom', async () => {
  const actual = await vi.importActual('react-router-dom');
  return {
    ...actual,
    useParams: () => useParamsMock(),
  };
});

vi.mock('../services/api', () => ({
  apiService: {
    getAtividadeById: vi.fn(),
    getSalas: vi.fn(),
    criarAtividade: vi.fn(),
    atualizarAtividade: vi.fn(),
  },
  setDefaultUser: vi.fn(),
}));

const mockSalas = [
  { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
  { id: 'sala-101', nome: 'Sala 101', capacidade: 40 },
  { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 },
];

const mockAtividadeEdit = {
  id: 'atv_001',
  titulo: 'Palestra de Abertura',
  tipo: 'palestra',
  salaId: 'auditorio',
  vagas: 200,
  encontros: [
    { id: 'enc_001', inicio: '2026-10-19T19:00:00-03:00', fim: '2026-10-19T22:00:00-03:00' },
  ],
  cargaHorariaMinutos: 180,
  situacao: 'prevista',
  ocupadas: 50,
  vagasRestantes: 150,
  emEspera: 0,
};

function renderForm() {
  apiService.getSalas.mockResolvedValue(mockSalas);
  if (useParamsMock().id) {
    apiService.getAtividadeById.mockResolvedValue(mockAtividadeEdit);
  } else {
    apiService.getAtividadeById.mockResolvedValue(null);
  }

  return render(<FormAtividadeModal onSuccess={vi.fn()} onClose={vi.fn()} />);
}

describe('FormAtividadeModal - Renderização do Formulário', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({});
  });

  it('renderiza o formulário de cadastro com todos os campos', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });
  });

  it('exibe campo Título', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByLabelText(/Título/)).toBeInTheDocument();
    });
  });

  it('exibe campo Tipo com opções palestra e minicurso', async () => {
    renderForm();

    await waitFor(() => {
      const select = screen.getByLabelText(/Tipo/);
      expect(select).toBeInTheDocument();
      expect(select.querySelectorAll('option')).toHaveLength(3);
    });
  });

  it('exibe campo Sala com opções carregadas da API', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByLabelText(/Sala/)).toBeInTheDocument();
    });
  });

  it('exibe campo Vagas', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByLabelText(/Vagas/)).toBeInTheDocument();
    });
  });

  it('exibe informações de tipo quando não está em modo de edição', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Palestra: exatamente 1 encontro')).toBeInTheDocument();
      expect(screen.getByText('Minicurso: de 2 a 5 encontros')).toBeInTheDocument();
    });
  });
});

describe('FormAtividadeModal - Modo de Edição', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({ id: 'atv_001' });
    apiService.getSalas.mockResolvedValue(mockSalas);
    apiService.getAtividadeById.mockResolvedValue(mockAtividadeEdit);
  });

  it('carrega dados da atividade no modo de edição', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Editar Atividade')).toBeInTheDocument();
    });

    await waitFor(() => {
      const tituloInput = screen.getByLabelText(/Título/);
      expect(tituloInput).toHaveValue('Palestra de Abertura');
    });
  });

  it('preenche campo sala com a atividade atual', async () => {
    renderForm();

    await waitFor(() => {
      const select = screen.getByLabelText(/Sala/);
      expect(select).toHaveValue('auditorio');
    });
  });

  it('exibe botão "Salvar Alterações" no modo de edição', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Salvar Alterações')).toBeInTheDocument();
    });
  });

  it('não exibe informações de tipo no modo de edição', async () => {
    renderForm();

    await waitFor(() => {
      expect(screen.queryByText('Palestra: exatamente 1 encontro')).not.toBeInTheDocument();
    });
  });
});

describe('FormAtividadeModal - Validação de Formulário', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({});
    apiService.getSalas.mockResolvedValue(mockSalas);
  });

  it('exibe erro de campo obrigatório ao submeter formulário vazio', async () => {
    const user = userEvent.setup();
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    const submitBtn = screen.getByText('Cadastrar Atividade');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText('Título é obrigatório')).toBeInTheDocument();
    });
    expect(screen.getByText('Tipo é obrigatório')).toBeInTheDocument();
    expect(screen.getByText('Sala é obrigatória')).toBeInTheDocument();
    expect(screen.getByText('Vagas deve ser maior que 0')).toBeInTheDocument();
  });

  it('exibe erro quando vagas é 0', async () => {
    const user = userEvent.setup();
    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText(/Título/), 'Teste');
    await user.selectOptions(screen.getByLabelText(/Tipo/), 'palestra');
    await user.selectOptions(screen.getByLabelText(/Sala/), 'auditorio');
    await user.type(screen.getByLabelText(/Vagas/), '0');

    const submitBtn = screen.getByText('Cadastrar Atividade');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText('Vagas deve ser maior que 0')).toBeInTheDocument();
    });
  });
});

describe('FormAtividadeModal - Submissão e Erros da API', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({});
    apiService.getSalas.mockResolvedValue(mockSalas);
  });

  it('exibe mensagem de sucesso ao criar atividade com sucesso', async () => {
    const user = userEvent.setup();
    apiService.criarAtividade.mockResolvedValue({ id: 'atv_new', titulo: 'Teste', tipo: 'palestra' });

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText(/Título/), 'Nova Palestra');
    await user.selectOptions(screen.getByLabelText(/Tipo/), 'palestra');
    await user.selectOptions(screen.getByLabelText(/Sala/), 'auditorio');
    await user.type(screen.getByLabelText(/Vagas/), '50');

    const submitBtn = screen.getByText('Cadastrar Atividade');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText('Atividade criada com sucesso!')).toBeInTheDocument();
    });
  });

  it('exibe mensagem de erro da API com código e mensagem ao falhar ao criar', async () => {
    const user = userEvent.setup();
    const error = new Error('Vagas acima da capacidade');
    error.code = 'VAGAS_ACIMA_DA_CAPACIDADE';
    apiService.criarAtividade.mockRejectedValue(error);

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText(/Título/), 'Nova Palestra');
    await user.selectOptions(screen.getByLabelText(/Tipo/), 'palestra');
    await user.selectOptions(screen.getByLabelText(/Sala/), 'auditorio');
    await user.type(screen.getByLabelText(/Vagas/), '300');

    const submitBtn = screen.getByText('Cadastrar Atividade');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText(/Erro da API \(VAGAS_ACIMA_DA_CAPACIDADE\)/)).toBeInTheDocument();
    });
    expect(screen.getByText(/Vagas acima da capacidade/)).toBeInTheDocument();
  });

  it('exibe mensagem de erro da API ao falhar ao atualizar', async () => {
    const user = userEvent.setup();
    useParamsMock.mockReturnValue({ id: 'atv_001' });
    const error = new Error('Atividade já iniciada');
    error.code = 'ATIVIDADE_JA_INICIADA';
    apiService.atualizarAtividade.mockRejectedValue(error);
    apiService.getSalas.mockResolvedValue(mockSalas);
    apiService.getAtividadeById.mockResolvedValue(mockAtividadeEdit);

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Editar Atividade')).toBeInTheDocument();
    });

    const submitBtn = screen.getByText('Salvar Alterações');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText(/Erro da API \(ATIVIDADE_JA_INICIADA\)/)).toBeInTheDocument();
    });
    expect(screen.getByText(/Atividade já iniciada/)).toBeInTheDocument();
  });

  it('limpa erros da API entre submissões', async () => {
    const user = userEvent.setup();
    const error = new Error('Erro qualquer');
    error.code = 'ERRO_TESTE';
    apiService.criarAtividade.mockRejectedValue(error);

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    await user.type(screen.getByLabelText(/Título/), 'Teste');
    await user.selectOptions(screen.getByLabelText(/Tipo/), 'palestra');
    await user.selectOptions(screen.getByLabelText(/Sala/), 'auditorio');
    await user.type(screen.getByLabelText(/Vagas/), '10');

    const submitBtn = screen.getByText('Cadastrar Atividade');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText(/Erro da API/)).toBeInTheDocument();
    });

    apiService.criarAtividade.mockResolvedValue({ id: 'atv_new', titulo: 'Teste' });
    apiService.criarAtividade.mockClear();

    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText('Atividade criada com sucesso!')).toBeInTheDocument();
    });
  });
});

describe('FormAtividadeModal - Submissão com Sucesso (Editar)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({ id: 'atv_001' });
    apiService.getSalas.mockResolvedValue(mockSalas);
    apiService.getAtividadeById.mockResolvedValue(mockAtividadeEdit);
    apiService.atualizarAtividade.mockResolvedValue({ id: 'atv_001', titulo: 'Atualizado' });
  });

  it('exibe mensagem de sucesso ao atualizar atividade', async () => {
    const user = userEvent.setup();

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Editar Atividade')).toBeInTheDocument();
    });

    const submitBtn = screen.getByText('Salvar Alterações');
    await user.click(submitBtn);

    await waitFor(() => {
      expect(screen.getByText('Atividade atualizada com sucesso!')).toBeInTheDocument();
    });
  });
});

describe('FormAtividadeModal - Fechar e Reset', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    useParamsMock.mockReturnValue({});
    apiService.getSalas.mockResolvedValue(mockSalas);
  });

  it('chama onClose ao clicar no botão cancelar', async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    const cancelBtn = screen.getByText('Cancelar');
    await user.click(cancelBtn);

    expect(onClose).toHaveBeenCalled();
  });

  it('fecha ao clicar no botão X do modal', async () => {
    const user = userEvent.setup();
    const onClose = vi.fn();

    renderForm();

    await waitFor(() => {
      expect(screen.getByText('Cadastrar Nova Atividade')).toBeInTheDocument();
    });

    const closeBtn = screen.getByText('×');
    await user.click(closeBtn);

    expect(onClose).toHaveBeenCalled();
  });
});

