  }
  useParamsMock.mockReturnValue(id ? { id } : {});

  return render(
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<FormAtividadeModal onSuccess={vi.fn()} onClose={onClose || vi.fn()} />} />
      </Routes>
